function pickHtml(j) {
  return j?.body ?? j?.data ?? j?.response ?? j?.html ?? j?.fetchedHtml ?? j?.content ?? j?.contentSnippet ?? j?.summary ?? j?.description ?? '';
}

function getMetaContent(html, propertyOrName) {
  const re = new RegExp(
    `<meta[^>]+(?:property|name)=[\"']${propertyOrName}[\"'][^>]+content=[\"']([^\"']+)[\"'][^>]*>`,
    'i'
  );
  const m = html.match(re);
  return m ? m[1].trim() : '';
}

function stripHtmlRough(html = '') {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map((item) => {
  const j = item.json;
  const html = pickHtml(j);

  const ogImage =
    getMetaContent(html, 'og:image') ||
    getMetaContent(html, 'twitter:image') ||
    '';
  const ogSite = getMetaContent(html, 'og:site_name') || '';
  const ogTitle = getMetaContent(html, 'og:title') || '';
  const ogDesc = getMetaContent(html, 'og:description') || '';

  const roughText = stripHtmlRough(html);

  return {
    json: {
      ...j,
      fetchedHtml: html,
      thumbnailUrl: j.thumbnailUrl || ogImage,
      site: j.site || ogSite,
      fetchedTitleHint: ogTitle,
      fetchedDescHint: ogDesc,
      fetchedTextRough: roughText
    }
  };
});

// FNV-1a 32bit（crypto不要）
function fnv1a32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  // unsigned 32bit → hex
  return (h >>> 0).toString(16).padStart(8, '0');
}

function stripHtml(html = '') {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeText(text = '', maxLen = 6000) {
  let t = String(text).replace(/\s+/g, ' ').trim();
  if (t.length > maxLen) t = t.slice(0, maxLen) + '…';
  return t;
}

function shouldPreSkip({ title, text }) {
  const t = (title || '').toLowerCase();
  if (t.includes('pr') || t.includes('広告') || t.includes('スポンサー')) return true;
  if (!text || text.length < 600) return true;
  return false;
}

function safeDate(v) {
  return v ? String(v) : '';
}

return items.map((item) => {
  const j = item.json;

  const title = j.title || j.fetchedTitleHint || '';
  const link = j.link ?? j.url ?? '';
  const publishedAt = safeDate(j.isoDate ?? j.pubDate ?? j.published ?? j.publishedAt ?? '');
  const feedUrl = j.feedUrl ?? '';

  const rssRaw = j.content ?? j.contentSnippet ?? j.summary ?? j.description ?? '';
  const rssText = normalizeText(stripHtml(rssRaw), 3000);

  const httpText = normalizeText(j.fetchedTextRough || '', 8000);
  const text = httpText.length > 800 ? httpText : rssText;

  const domain = (() => { try { return new URL(link).hostname; } catch { return ''; } })();
  const hashBase = `${title}\n${domain}\n${text.slice(0, 2000)}`;
  const hash = fnv1a32(hashBase);

  const preSkip = shouldPreSkip({ title, text });

  // Gemini: 分類/タグ/重要度/summary/action + カラム分割
  const geminiInput = {
    task: "rss_article_classify_and_split",
    input: {
      title,
      link,
      feedUrl,
      site: j.site || domain,
      publishedAt,
      thumbnailUrl: j.thumbnailUrl || '',
      text
    },
    output_schema: {
      action: "string (input|skip|review)",
      tags: "string[]",
      importance: "integer (1-5)",
      summary: "string (日本語 5-7行)",
      columns: {
        source: "string (ソース名の推定/整形)",
        site: "string (サイト名)",
        topics: "string[]",
        entities: "string[]",
        why: "string (短く)"
      }
    },
    constraints: [
      "出力はJSONのみ",
      "憶測で断定しない",
      "広告/PR/同内容/低情報量なら action=skip を推奨",
      "タグは短く、最大10個程度"
    ]
  };

  return {
    json: {
      ...j,
      title,
      link,
      feedUrl,
      site: j.site || domain,
      thumbnailUrl: j.thumbnailUrl || '',
      publishedAt,
      normalizedText: text,
      hash,
      preSkip,
      geminiPrompt: JSON.stringify(geminiInput),

      // Notion初期値
      readStatus: "Unread",
      source: feedUrl || domain
    }
  };
});

// Parse/Type(Code) 置換：元データ保持 + 最低限Notion用フィールド生成
function pick(obj, path, fallback = '') {
  try {
    return path.split('.').reduce((a, k) => (a && a[k] != null ? a[k] : null), obj) ?? fallback;
  } catch { return fallback; }
}

return items.map(item => {
  // ここで item.json が {"exists":false} だけなら、前段が上書きしています
  const j = item.json ?? {};

  // exists は前段SQLの結果から来ているはず
  const exists = !!j.exists;

  // 元データが残っている前提で Notion用を作る（無ければ空になる）
  const title = j.title || j.fetchedTitleHint || 'RSS item';
  const link = j.link || j.resolvedUrl || '';
  const publishedAt = j.publishedAt || '';
  const hash = j.hash || '';

  // Gemini未実行でも落ちないデフォルト
  const action = j.action || (j.preSkip ? 'skip' : 'input');
  const importance = Number.isFinite(Number(j.importance)) ? Number(j.importance) : 3;
  const tags = Array.isArray(j.tags) ? j.tags : [];
  const summary = j.summary || '';

  return {
    json: {
      ...j,
      exists,

      // Notion blockが参照するキー（ここを統一）
      title,
      link,
      publishedAt,
      hash,
      action,
      importance,
      tags,
      summary,
      source: j.source || j.feedUrl || j.site || '',
      site: j.site || '',

      // Drive用（後でConvert to Fileで使う）
      driveFileName: `${hash || 'nohash'}__${title.replace(/[\\/:*?"<>|]/g,'_').slice(0,60)}.txt`,
      driveText: `Title: ${title}\nURL: ${link}\nPublishedAt: ${publishedAt}\nHash: ${hash}\n\nSummary:\n${summary}\n\nBody:\n${j.normalizedText || ''}\n`
    }
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

