SELECT EXISTS(
  SELECT 1 FROM dedup_hashes WHERE hash = $1
) AS exists;

INSERT INTO dedup_hashes(hash, url, published_at, source)
VALUES ($1, $2, $3, $4)
ON CONFLICT (hash) DO NOTHING;

