function tryDecode(s) {
  try { return decodeURIComponent(s); } catch { return s; }
}
function decodeTwice(s) {
  return tryDecode(tryDecode(s));
}
function extractByRegex(u) {
  const m = String(u).match(/[?&](?:url|q|u)=([^&]+)/i);
  return m ? decodeTwice(m[1]) : '';
}
function unwrap(u) {
  let parsed;
  try { parsed = new URL(u); } catch { return u; }

  const isGoogle = (parsed.hostname === 'www.google.com' || parsed.hostname === 'google.com');
  if (!isGoogle || parsed.pathname !== '/url') return u;

  const raw =
    parsed.searchParams.get('url') ||
    parsed.searchParams.get('q') ||
    parsed.searchParams.get('u') ||
    '';

  const cand = raw ? decodeTwice(raw) : '';
  return cand || u;
}

return items.map(item => {
  const j = item.json ?? {};
  const link = j.link ?? j.url ?? '';

  const fromRegex = extractByRegex(link);
  const fromSearchParams = (() => {
    try {
      const p = new URL(link);
      return p.searchParams.get('url') || p.searchParams.get('q') || p.searchParams.get('u') || '';
    } catch { return ''; }
  })();

  // ★ここが肝：regex優先で resolvedUrl を確定
  const resolvedUrl = (fromRegex || decodeTwice(fromSearchParams) || unwrap(link)).trim();

  return {
    json: {
      ...j,
      resolvedUrl,
      _debug_raw: link,
      _debug_fromRegex: fromRegex,
      _debug_fromSearchParams: fromSearchParams
    }
  };
});
